import os
from ta5g_enb import ta5g_enb
from ta5g_iphy import ta5g_iphy
from ta5g_setups_and_teardowns import ta5g_setups_and_teardowns
from taf.ul.ettf.logging.collector import Collector
from taf.ul.ettf.typed.custom_types import Filepath, Ip
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.config.globals import DEFAULT_REMOTE_HOST, IPHY0_LMP_IP
from taf.ul.ettf.utils.robot_handlers import with_callback_name
from taf.ul.ettf.logger import custom_logger


logger = custom_logger('logging.configs')


class GnbSwconfigCollector(Collector):
    @typed(logs_directory=Filepath(), remote_host=Ip())
    def __init__(self, logs_directory, remote_host=DEFAULT_REMOTE_HOST):
        super(GnbSwconfigCollector, self).__init__()
        self._swconfig_filepath = os.path.join(logs_directory, 'swconfig_gnb.txt')
        self._remote_host = remote_host
        self._gnb_access = ta5g_enb()

    @with_callback_name('Collect Gnb Sw Config')
    def stop(self):
        self._gnb_access.get_swconfig_file(self._swconfig_filepath, self._remote_host)


