class SosReportCollector(Collector):
    @typed(logs_directory=Filepath())
    def __init__(self, logs_directory):
        super(SosReportCollector, self).__init__()
        self._logs_directory = logs_directory
        self._setups_and_teardowns_access = ta5g_setups_and_teardowns()

    @with_callback_name('Collect SosReport')
    def stop(self):
        logger.debug('Start collecting Iphy sosReport')
        self._setups_and_teardowns_access.collect_sos_report(self._logs_directory)
